const visual = {
  prepare: function (input) {
    var texts = ['F(x) = F0 (1 - x/h)', 'F', 'x', '0', 'h/2', 'h', 'F0', 'F0/2', 'S = 3/8 F0 h = 0.375 F0 h'];
    var out = [];
    for (var i = 0; i < texts.length; i++) { out.push({ kind: 'text', payload: texts[i] }); }
    return out;
  },
  render: function (input, metrics) {
    var W = input.viewport.widthDu;
    var H = input.viewport.heightDu;
    var x0 = Math.round(W * 0.14);
    var x1 = Math.round(W * 0.93);
    var baseY = Math.round(H * 0.80);
    var topY = Math.round(H * 0.18);
    var fs = Math.max(11, Math.round(H * 0.034));
    var X = function (t) { return x0 + t * (x1 - x0); };
    var Y = function (f) { return baseY - f * (baseY - topY); };
    var halfX = X(0.5);
    var shade = ['M', x0, baseY, 'L', x0, Y(1), 'L', halfX, Y(0.5), 'L', halfX, baseY, 'Z'];
    var curve = visualSdk.polyline([[x0, Y(1)], [x1, Y(0)]]);
    var xAxis = visualSdk.polyline([[x0 - 8, baseY], [x1 + 14, baseY]]);
    var yAxis = visualSdk.polyline([[x0, baseY + 8], [x0, topY - 14]]);
    var ticks = ['M', halfX, baseY, 'L', halfX, baseY + 7, 'M', x1, baseY, 'L', x1, baseY + 7, 'M', x0 - 7, Y(0.5), 'L', x0, Y(0.5), 'M', x0 - 7, Y(1), 'L', x0, Y(1)];
    var edge = ['M', halfX, Y(0.5), 'L', halfX, baseY];
    var dot = visualSdk.circle(halfX, Y(0.5), 3.5);
    var eqY = Math.max(fs * 1.4, topY - 26);
    var labels = [
      { type: 'label', x: x0, y: eqY, text: 'F(x) = F0 (1 - x/h)', fontSize: fs, fill: '#1f2d3d', anchor: 'start' },
      { type: 'label', x: x0 - 16, y: Math.max(fs, topY - 4), text: 'F', fontSize: fs, fill: '#1f2d3d', anchor: 'end' },
      { type: 'label', x: Math.min(W - 6, x1 + 18), y: baseY + fs * 0.36, text: 'x', fontSize: fs, fill: '#1f2d3d', anchor: 'start' },
      { type: 'label', x: x0 - 16, y: baseY + fs * 0.9, text: '0', fontSize: fs, fill: '#1f2d3d', anchor: 'end' },
      { type: 'label', x: halfX, y: baseY + fs * 1.6, text: 'h/2', fontSize: fs, fill: '#1f2d3d', anchor: 'middle' },
      { type: 'label', x: x1, y: baseY + fs * 1.6, text: 'h', fontSize: fs, fill: '#1f2d3d', anchor: 'middle' },
      { type: 'label', x: x0 - 16, y: Y(1) + fs * 0.36, text: 'F0', fontSize: fs, fill: '#1f2d3d', anchor: 'end' },
      { type: 'label', x: x0 - 16, y: Y(0.5) + fs * 0.36, text: 'F0/2', fontSize: fs, fill: '#1f2d3d', anchor: 'end' },
      { type: 'label', x: X(0.30), y: baseY - fs * 1.8, text: 'S = 3/8 F0 h = 0.375 F0 h', fontSize: fs, fill: '#1c4a86', anchor: 'middle' }
    ];
    var children = [
      { type: 'path', pathId: 'shade', fill: '#cfe2f7', stroke: 'none' },
      { type: 'path', pathId: 'edge', stroke: '#5b7fb0', strokeWidth: 1.2 },
      { type: 'path', pathId: 'curve', stroke: '#c0392b', strokeWidth: 2.2 },
      { type: 'path', pathId: 'xaxis', stroke: '#26354a', strokeWidth: 1.6 },
      { type: 'path', pathId: 'yaxis', stroke: '#26354a', strokeWidth: 1.6 },
      { type: 'path', pathId: 'ticks', stroke: '#26354a', strokeWidth: 1.4 },
      { type: 'path', pathId: 'dot', fill: '#c0392b', stroke: 'none' }
    ];
    for (var i = 0; i < labels.length; i++) { children.push(labels[i]); }
    return {
      schemaVersion: 1,
      sceneId: 'fig-f0-linear-shaded',
      revision: input.revision,
      viewBox: { x: 0, y: 0, width: W, height: H },
      paths: [
        { id: 'shade', commands: shade },
        { id: 'edge', commands: edge },
        { id: 'curve', commands: curve },
        { id: 'xaxis', commands: xAxis },
        { id: 'yaxis', commands: yAxis },
        { id: 'ticks', commands: ticks },
        { id: 'dot', commands: dot }
      ],
      root: { type: 'group', children: children }
    };
  }
};
